import type { FetchBody, UserInfoResponse } from "openid-client";

/**
 * PluginAuthConfig
 * Config generated by plugin used to configure oauth2 operations
 */

export interface PluginAuthConfig {
    server: string;
    clientId: string;
    clientSecret: string;
    scope: string[];
}

/**
 * PluginAuthRequest | PluginAuthResponse
 * Data passed to plugin hooks for handleing oauth2 operations
 */

export interface FetchOptions {
    method?: string;
    body?: FetchBody;
    headers?: Headers;
}

export interface PluginAuthRequest {
    userInfo: UserInfoResponse;
    fetch: (url: URL, options?: FetchOptions) => Promise<Response>;
}

// If tokens have expired null will be passed since
// new data cannot be fetched
export type PluginAuthRefresh = PluginAuthRequest | null;

/**
 * PluginAuthSystemInfo
 * Data passed to widget rendering hooks, contains data about configured
 * oauth2 client
 */

export interface PluginAuthSystemInfo {
    loginUrl: string;
}